package com.hueyhelper;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("hueyhelper")
public interface HueyHelperConfig extends Config {

	// --- ENUMS FOR DROPDOWNS ---
	public enum PanelFontType {
		SMALL("RS Small"),
		REGULAR("RS Regular"),
		BOLD("RS Bold"),
		QUILL("Quill"),
		QUILL_CAPS("Quill Caps"),
		BARBARIAN("Barb Assault"),
		BEBAS_NEUE("Bebas Neue");

		private final String name;
		PanelFontType(String name) { this.name = name; }
		@Override public String toString() { return name; }
	}

	// --- SECTIONS ---

	@ConfigSection(name = "Overlay", description = "Settings for the live fight overlay", position = 0)
	String overlaySection = "overlay";

	@ConfigSection(name = "Side Panel", description = "Settings for the RuneLite side panel", position = 1)
	String sidePanelSection = "sidePanel";

	@ConfigSection(name = "Other", description = "Other general settings", position = 2)
	String otherSection = "other";

	@ConfigSection(name = "Debug", description = "Debugging tools for development", position = 3)
	String debugSection = "debug";

	// --- OVERLAY SETTINGS ---

	@ConfigItem(keyName = "showOverlay", name = "Show Live Fight Stats", description = "Shows the live fight statistics overlay", position = 1, section = overlaySection)
	default boolean showOverlay() { return true; }

	@ConfigItem(keyName = "showEligibilityInfoBox", name = "Show Eligibility InfoBox", description = "Shows a green/red marker box indicating if you have qualified for loot", position = 2, section = overlaySection)
	default boolean showEligibilityInfoBox() { return true; }

	@ConfigItem(keyName = "showParticipants", name = "Show Participants", description = "Shows the number of players in the arena", position = 3, section = overlaySection)
	default boolean showParticipants() { return true; }

	@ConfigItem(keyName = "showPhaseDamage", name = "Show Phase Damage", description = "Shows your damage for Phase 1 and Phase 2", position = 4, section = overlaySection)
	default boolean showPhaseDamage() { return true; }

	@ConfigItem(keyName = "showPercentages", name = "Show Damage Percentages", description = "Shows the % of the boss's total HP you have dealt", position = 5, section = overlaySection)
	default boolean showPercentages() { return true; }

	@ConfigItem(keyName = "showContribution", name = "Show Reward %", description = "Shows your calculated loot contribution percentage", position = 6, section = overlaySection)
	default boolean showContribution() { return true; }

	@ConfigItem(keyName = "showDropRates", name = "Show Rare Drop Rates", description = "Shows your dynamic drop rates for the unique items", position = 7, section = overlaySection)
	default boolean showDropRates() { return true; }

	@ConfigItem(
			position = 8,
			section = overlaySection,
			keyName = "highlightBody",
			name = "Highlight Hueycoatl Body",
			description = "Draws a visual highlight around the boss's body."
	)
	default boolean highlightBody() {
		return true;
	}

	@ConfigItem(
			position = 9,
			section = overlaySection,
			keyName = "showTileMarkers",
			name = "Show Arena Tile Markers",
			description = "Highlights the floor tiles to help learn boss mechanics"
	)
	default boolean showTileMarkers() {
		return true;
	}

	@ConfigItem(
			position = 10,
			section = overlaySection,
			keyName = "showTileText",
			name = "Show Mechanic Text",
			description = "Displays the mechanic instructions hovering over the guide tiles"

	)
	default boolean showTileText() {
		return true;
	}

	// --- SIDE PANEL SETTINGS ---
	@ConfigItem(keyName = "panelFont", name = "Panel Font", description = "Choose the font style for the entire side panel", position = 1, section = sidePanelSection)
	default PanelFontType panelFont() { return PanelFontType.BEBAS_NEUE; }

	// --- OTHER SETTINGS ---

	@ConfigItem(keyName = "persistLoot", name = "Save Loot Tracker on Close", description = "Remembers your loot and KC even if you close RuneLite", position = 1, section = otherSection)
	default boolean persistLoot() { return true; }

	@ConfigItem(keyName = "autoSaveKills", name = "Auto-save CSV Log", description = "Automatically updates the CSV file after every kill", position = 2, section = otherSection)
	default boolean autoSaveKills() { return true; }

	@ConfigItem(
			keyName = "autoHidePanel",
			name = "Auto-Hide Plugin Panel",
			description = "Hides the sidebar icon when you aren't in The Darkfrost",
			position = 3,
			section = otherSection
	)
	default boolean autoHidePanel() {
		return false;
	}

	// --- DEBUG SETTINGS ---

	@ConfigItem(keyName = "debugStateBox", name = "Show Arena and State", description = "Shows the live State Machine data box in the top right", position = 1, section = debugSection)
	default boolean debugStateBox() { return false; }

	@ConfigItem(keyName = "debugArenaInfoBox", name = "Show Arena InfoBox", description = "Shows a green tick / red X InfoBox based on your arena status", position = 2, section = debugSection)
	default boolean debugArenaInfoBox() { return false; }

	@ConfigItem(keyName = "debugHighlightedArena", name = "Show Highlighted arena", description = "Draws the green safe zone tiles on the floor and minimap", position = 3, section = debugSection)
	default boolean debugHighlightedArena() { return false; }
}

package com.hueyhelper;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Collection;

public class HueyHelperDebugOverlay extends OverlayPanel
{
    private final Client client;
    private final HueyHelperPlugin plugin;
    private final HueyHelperConfig config;

    @Inject
    public HueyHelperDebugOverlay(Client client, HueyHelperPlugin plugin, HueyHelperConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_RIGHT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        boolean showBox = config.debugStateBox();
        boolean showTiles = config.debugHighlightedArena();

        if (!showBox && !showTiles) return null;

        // Grab the modern WorldView to handle coordinates safely
        WorldView wv = client.getTopLevelWorldView();
        if (wv == null) return null;

        // 1. Loop through and draw each background tile individually to snap them to the floor
        if (showTiles) {
            int z = wv.getPlane();
            for (int packed : plugin.getArenaTiles()) {
                int wx = packed >> 16;
                int wy = packed & 0xFFFF;
                drawTile(graphics, wv, wx, wy, z);
            }
        }

        // 2. Render the Debug Text Box
        if (showBox) {
            panelComponent.getChildren().clear();
            panelComponent.getChildren().add(TitleComponent.builder().text("Huey Debugger").color(Color.YELLOW).build());
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("In Arena Zone:")
                    .right(plugin.isInArena() ? "YES" : "NO")
                    .rightColor(plugin.isInArena() ? Color.GREEN : Color.RED)
                    .build());
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("State Machine:")
                    .right("Phase " + plugin.getCurrentFightPhase())
                    .rightColor(Color.CYAN)
                    .build());

            return super.render(graphics);
        }

        return null;
    }

    /**
     * Translates a specific coordinate into the current instance and draws it snapped directly to the ground.
     */
    private void drawTile(Graphics2D graphics, WorldView wv, int wx, int wy, int plane) {
        WorldPoint templateWp = new WorldPoint(wx, wy, plane);

        // Translate the static region points safely into the instanced world view
        Collection<WorldPoint> activePoints = WorldPoint.toLocalInstance(wv, templateWp);

        for (WorldPoint activeWp : activePoints) {
            LocalPoint lp = LocalPoint.fromWorld(wv, activeWp);

            if (lp != null) {
                // Get the individual 3D canvas tile polygon from the local height map
                Polygon poly = Perspective.getCanvasTilePoly(client, lp);
                if (poly != null) {
                    graphics.setStroke(new BasicStroke(1));
                    graphics.setColor(new Color(0, 255, 255, 30)); // Subtle Cyan fill
                    graphics.fillPolygon(poly);
                    graphics.setColor(new Color(0, 255, 255, 90)); // Clean Cyan outline
                    graphics.drawPolygon(poly);
                }

                // Match the visual tracking directly onto the game minimap
                Point minimapPoint = Perspective.localToMinimap(client, lp);
                if (minimapPoint != null) {
                    graphics.setColor(new Color(0, 255, 255, 60));
                    graphics.fillRect(minimapPoint.getX(), minimapPoint.getY(), 1, 1);
                }
            }
        }
    }
}

package com.hueyhelper;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;
import java.text.DecimalFormat;

public class HueyHelperOverlay extends OverlayPanel
{
    private final HueyHelperPlugin plugin;
    private final HueyHelperConfig config;

    private static final int MAX_BODY_HP = 1250;
    private static final int MAX_HEAD_TAIL_HP = 2800;
    private static final int TOTAL_HP = 4050;
    private final DecimalFormat df = new DecimalFormat("#.##");

    @Inject
    public HueyHelperOverlay(HueyHelperPlugin plugin, HueyHelperConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showOverlay() || !plugin.isInArena()) return null;

        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder().text("Huey Helper").color(Color.ORANGE).build());

        int pCount = plugin.getParticipantCount();

        if (config.showParticipants())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Participants:")
                    .right(pCount + "/20")
                    .build());
        }

        int myBody = plugin.getBodyDamage();
        int myHeadTail = plugin.getHeadTailTotal();
        int myTotal = myBody + myHeadTail;

        boolean phase1Passed = myBody >= 25;
        boolean phase2Passed = myHeadTail >= 75;
        boolean totalPassed = myTotal >= 75; // <--- ADD THIS
        boolean isMass = pCount >= 6;

// Check Total Damage instead of Phase 2 alone for Masses:
        boolean isEligible = isMass ? (phase1Passed || totalPassed) : (phase1Passed && phase2Passed);

        if (config.showPhaseDamage())
        {
            double bodyContrib = Math.min((double) myBody / MAX_BODY_HP, 1.0);
            double htContrib = Math.min((double) myHeadTail / MAX_HEAD_TAIL_HP, 1.0);

            Color bodyColor = phase1Passed ? Color.GREEN : Color.RED;
            Color headTailColor;

            // Turn Phase 2 text green if total damage passes in mass
            if (phase2Passed || (isMass && totalPassed)) {
                headTailColor = Color.GREEN;
            } else if (isMass && phase1Passed) {
                headTailColor = Color.GRAY;
            } else {
                headTailColor = Color.RED;
            }

            String bodyRight = config.showPercentages() ? myBody + " (" + df.format(bodyContrib * 100) + "%)" : String.valueOf(myBody);
            String htRight = config.showPercentages() ? myHeadTail + " (" + df.format(htContrib * 100) + "%)" : String.valueOf(myHeadTail);

            panelComponent.getChildren().add(LineComponent.builder().left("Phase 1:").right(bodyRight).rightColor(bodyColor).build());
            panelComponent.getChildren().add(LineComponent.builder().left("Phase 2:").right(htRight).rightColor(headTailColor).build());
        }

        if (config.showContribution() && myTotal > 0)
        {
            String contribText;
            double calc = (double) myTotal / TOTAL_HP;

            if (isMass) {
                contribText = (calc <= 0.05) ? "5% (Mass Protection)" : df.format(calc * 100) + "% (Assumed)";
            } else if (phase1Passed && phase2Passed) {
                contribText = (calc <= 0.05) ? "5% (Rounded up)" : df.format(calc * 100) + "% (Assumed)";
            } else {
                contribText = "5% (95% Penalty)";
            }

            Color contribColor = isEligible ? Color.GREEN : Color.RED;
            panelComponent.getChildren().add(LineComponent.builder().left("Reward %:").right(contribText).rightColor(contribColor).build());
        }

        if (config.showDropRates() && myTotal > 0)
        {
            if (!isEligible)
            {
                Color dropColor = Color.RED;
                panelComponent.getChildren().add(LineComponent.builder().left("Hide:").right("None").rightColor(dropColor).build());
                panelComponent.getChildren().add(LineComponent.builder().left("Tome:").right("None").rightColor(dropColor).build());
                panelComponent.getChildren().add(LineComponent.builder().left("Wand:").right("None").rightColor(dropColor).build());
                panelComponent.getChildren().add(LineComponent.builder().left("Pet:").right("None").rightColor(dropColor).build());
            }
            else
            {
                double dropMathContrib = Math.max(Math.min((double) myTotal / TOTAL_HP, 1.0), 0.05);

                // Keep the color change for visual feedback, but remove the redundant 20x multiplier
                Color petColor = phase1Passed ? Color.GREEN : Color.ORANGE;
                Color dropColor = Color.GREEN;

                panelComponent.getChildren().add(LineComponent.builder().left("Hide:").right("~1/" + df.format(28.64 / dropMathContrib)).rightColor(dropColor).build());
                panelComponent.getChildren().add(LineComponent.builder().left("Tome:").right("~1/" + df.format(90.0 / dropMathContrib)).rightColor(dropColor).build());
                panelComponent.getChildren().add(LineComponent.builder().left("Wand:").right("~1/" + df.format(105.0 / dropMathContrib)).rightColor(dropColor).build());
                panelComponent.getChildren().add(LineComponent.builder().left("Pet:").right("~1/" + df.format(400.0 / dropMathContrib)).rightColor(petColor).build());
            }
        }

        return super.render(graphics);
    }
}

